selector_to_html = {"a[href=\"#pyskyfire.thermo.state.PHASE_LIQUID\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.state.PHASE_LIQUID\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.state.</span></span><span class=\"sig-name descname\"><span class=\"pre\">PHASE_LIQUID</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">'liquid'</span></span></dt><dd></dd>", "a[href=\"#module-pyskyfire.thermo.state\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.thermo.state<a class=\"headerlink\" href=\"#module-pyskyfire.thermo.state\" title=\"Link to this heading\">\u00b6</a></h1><p>CoolProp-backed fluid state resolution, including the saturation dome.</p><p>Specific enthalpy and pressure identify states through the boiling dome,\nwhere temperature and pressure alone cannot determine vapour quality.\n<code class=\"docutils literal notranslate\"><span class=\"pre\">FluidStateResolver</span></code> caches saturation data and resolves bulk states using\nhomogeneous (no-slip) two-phase density. <code class=\"docutils literal notranslate\"><span class=\"pre\">probe_fluid</span></code> reports whether the\nbackend supports enthalpy-based resolution and saturation properties.</p>", "a[href=\"SaturationState.html#pyskyfire.thermo.state.SaturationState\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.state.SaturationState\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.state.</span></span><span class=\"sig-name descname\"><span class=\"pre\">SaturationState</span></span></dt><dd><p>Saturation properties at one pressure.</p><p>Built once per axial station and cached, so that the inner wall solve \u2013\nwhich may evaluate the fluid side a couple of hundred times per node \u2013\nnever triggers a flash.</p></dd>", "a[href=\"#pyskyfire.thermo.state.PHASE_SUPERCRITICAL\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.state.PHASE_SUPERCRITICAL\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.state.</span></span><span class=\"sig-name descname\"><span class=\"pre\">PHASE_SUPERCRITICAL</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">'supercritical'</span></span></dt><dd></dd>", "a[href=\"#pyskyfire.thermo.state.PHASE_VAPOUR\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.state.PHASE_VAPOUR\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.state.</span></span><span class=\"sig-name descname\"><span class=\"pre\">PHASE_VAPOUR</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">'vapour'</span></span></dt><dd></dd>", "a[href=\"#module-contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Contents<a class=\"headerlink\" href=\"#module-contents\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.thermo.state.PHASE_TWO_PHASE\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.state.PHASE_TWO_PHASE\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.state.</span></span><span class=\"sig-name descname\"><span class=\"pre\">PHASE_TWO_PHASE</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">'two_phase'</span></span></dt><dd></dd>", "a[href=\"#pyskyfire.thermo.state.probe_fluid\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.state.probe_fluid\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.state.</span></span><span class=\"sig-name descname\"><span class=\"pre\">probe_fluid</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fluid</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_ref</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"FluidCapability.html#pyskyfire.thermo.state.FluidCapability\" title=\"pyskyfire.thermo.state.FluidCapability\"><span class=\"pre\">FluidCapability</span></a></span></span></dt><dd><p>Determine what two-phase support a CoolProp fluid string has.</p><p>Run once per solve, at the inlet pressure. Cheap: a handful of property\ncalls.</p><p class=\"rubric\">Notes</p><p>The critical-pressure probe is deliberately tolerant. <code class=\"docutils literal notranslate\"><span class=\"pre\">Props1SI</span></code> refuses\nmixtures outright, and <code class=\"docutils literal notranslate\"><span class=\"pre\">AbstractState.p_critical()</span></code> can fail even for\nwell-behaved binaries (ethanol/water reports \u201cfound 4 critical points\u201d), so\na missing critical point downgrades the capability rather than raising.</p></dd>", "a[href=\"#attributes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.thermo.state.PHASE_UNKNOWN\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.state.PHASE_UNKNOWN\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.state.</span></span><span class=\"sig-name descname\"><span class=\"pre\">PHASE_UNKNOWN</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">'unknown'</span></span></dt><dd></dd>", "a[href=\"FluidCapability.html#pyskyfire.thermo.state.FluidCapability\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.state.FluidCapability\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.state.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FluidCapability</span></span></dt><dd><p>What two-phase machinery is usable for a given fluid.</p></dd>", "a[href=\"FluidStateResolver.html#pyskyfire.thermo.state.FluidStateResolver\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.state.FluidStateResolver\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.state.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FluidStateResolver</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">transport</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_ref</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Resolve fluid states from <code class=\"docutils literal notranslate\"><span class=\"pre\">(h,</span> <span class=\"pre\">p)</span></code>, with cached saturation data.</p></dd>", "a[href=\"FluidState.html#pyskyfire.thermo.state.FluidState\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.state.FluidState\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.state.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FluidState</span></span></dt><dd><p>Resolved bulk fluid state at one axial station.</p></dd>", "a[href=\"#functions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Functions<a class=\"headerlink\" href=\"#functions\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
